import type { Database } from "./db.ts";

export interface Task {
  id: number;
  title: string;
  created_at: string;
  updated_at: string;
  completed_at: string | null;
}

export interface DeletedTask extends Task {
  deleted_at: string;
}

const TASK_COLUMNS = "id, title, created_at, updated_at, completed_at";

export function listTasks(db: Database): Task[] {
  return db.all(
    `SELECT ${TASK_COLUMNS} FROM tasks WHERE deleted_at IS NULL ORDER BY id`,
  ) as unknown as Task[];
}

export function createTask(db: Database, title: string): Task {
  const now = new Date().toISOString();
  const [task] = db.all(
    `INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?) RETURNING ${TASK_COLUMNS}`,
    title.trim(),
    now,
    now,
  );
  return task as unknown as Task;
}

/** Deleted tasks, most recently deleted first. */
export function listDeletedTasks(db: Database): DeletedTask[] {
  return db.all(
    `SELECT ${TASK_COLUMNS}, deleted_at FROM tasks WHERE deleted_at IS NOT NULL
     ORDER BY deleted_at DESC, id DESC`,
  ) as unknown as DeletedTask[];
}

/** Soft-deletes a task. Returns false when no live task has this id (missing or already deleted). */
export function deleteTask(db: Database, id: number): boolean {
  const rows = db.all(
    "UPDATE tasks SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL RETURNING id",
    new Date().toISOString(),
    id,
  );
  return rows.length === 1;
}

/** Brings a deleted task back. Restoring a task that is not deleted is a no-op; null means no such id. */
export function restoreTask(db: Database, id: number): Task | null {
  const [task] = db.all(
    `UPDATE tasks SET deleted_at = NULL WHERE id = ? AND deleted_at IS NOT NULL
     RETURNING ${TASK_COLUMNS}`,
    id,
  );
  if (task) return task as unknown as Task;
  const [existing] = db.all(`SELECT ${TASK_COLUMNS} FROM tasks WHERE id = ?`, id);
  return (existing as unknown as Task | undefined) ?? null;
}
EOF
